INSERT INTO oms_fulfillment_plan (
    plan_id, tenant_id, order_id, status, split_shipment, partial_shipment,
    estimated_shipping_cost, created_at, updated_at
)
VALUES (
    #{planId}, #{tenantId}, #{orderId}, #{status}, #{splitShipment}, #{partialShipment},
    #{estimatedShippingCost}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE oms_fulfillment_plan
SET status = #{status},
    split_shipment = #{splitShipment},
    partial_shipment = #{partialShipment},
    estimated_shipping_cost = #{estimatedShippingCost},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND order_id = #{orderId}

mapper.select:
SELECT plan_id, tenant_id, order_id, status, split_shipment, partial_shipment,
       estimated_shipping_cost, created_at, updated_at
FROM oms_fulfillment_plan
WHERE tenant_id = #{tenantId}
  AND order_id = #{orderId}

SELECT plan_id, tenant_id, order_id, status, split_shipment, partial_shipment,
       estimated_shipping_cost, created_at, updated_at
FROM oms_fulfillment_plan
WHERE tenant_id = #{tenantId}
  AND plan_id = #{planId}

